-- Fiche Mes goûts (CE2) - anglais, notion 'en_gouts'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce2', 'english', 'Mes goûts', $fiche$
